        # Check if book is already borrowed
        if self.books[book_id] is not None:
            raise ValueError(f"Book {book_id} is already borrowed")

        # Check if user already has a book (if they have unpaid fines)
        if user in self.users and self.users[user]['unpaid_fines'] > 0:
            if self.users[user]['current_book'] is not None:
                raise ValueError(f"User {user} already has a book and has unpaid fines")

        # Borrow the book
        self.books[book_id] = {'borrowed_by': user, 'borrow_date': day}

        # Initialize user if not exists
        if user not in self.users:
            self.users[user] = {'current_book': book_id, 'unpaid_fines': 0.0}
        else:
            self.users[user]['current_book'] = book_id

    def return_book(self, user: str, book_id: str, day: date) -> float:
        # Check if book exists
        if book_id not in self.books:
            raise ValueError(f"Book {book_id} does not exist")

        # Check if book is borrowed by this user
        if self.books[book_id] is None:
            raise ValueError(f"Book {book_id} is not borrowed")
        if self.books[book_id]['borrowed_by'] != user:
            raise ValueError(f"Book {book_id} is not borrowed by user {user}")

        # Calculate fine
        borrow_date = self.books[book_id]['borrow_date']
        due_date = date(borrow_date.year, borrow_date.month, borrow_date.day) + \
                   self._days_to_timedelta(self.loan_days)

        fine = 0.0
        if day > due_date:
            # Calculate days late
            days_late = (day - due_date).days
            fine = days_late * self.daily_fine

        # Update book status
        self.books[book_id] = None

        # Update user status
        if user in self.users:
            self.users[user]['current_book'] = None
            self.users[user]['unpaid_fines'] += fine

        return fine

    def unpaid_fines(self, user: str) -> float:
        if user not in self.users:
            return 0.0
        return self.users[user]['unpaid_fines']

    def pay(self, user: str) -> None:
        if user in self.users:
            self.users[user]['unpaid_fines'] = 0.0

    def _days_to_timedelta(self, days: int):
        """Helper to convert days to timedelta (since we can't use timedelta directly in some contexts)"""
        from datetime import timedelta
        return timedelta(days=days)
